package vn.eventplatform.ad.service;
import lombok.RequiredArgsConstructor; import org.springframework.cache.annotation.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.eventplatform.ad.domain.*; import vn.eventplatform.ad.dto.*; import vn.eventplatform.ad.enums.*; import vn.eventplatform.ad.repository.*; import vn.eventplatform.common.dto.ErrorCode; import vn.eventplatform.common.exception.AppException; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AdService { private final AdPackageRepository packages; private final AdCampaignRepository campaigns; private final BannerRepository banners;
 public Responses.PackageResponse packageCreate(Requests.PackageRequest r){AdPackage p=new AdPackage();p.setName(r.name());p.setDescription(r.description());p.setPrice(r.price());p.setDurationDays(r.durationDays());p.setActive(r.active()==null||r.active());return pkg(packages.save(p));} public List<Responses.PackageResponse> packageAll(){return packages.findAll().stream().map(this::pkg).toList();} public Responses.PackageResponse packageUpdate(UUID id,Requests.PackageRequest r){AdPackage p=packageById(id);p.setName(r.name());p.setDescription(r.description());p.setPrice(r.price());p.setDurationDays(r.durationDays());if(r.active()!=null)p.setActive(r.active());return pkg(packages.save(p));} public void packageDelete(UUID id){packages.delete(packageById(id));}
 @Transactional public Responses.CampaignResponse register(UUID organizer,Requests.CampaignRequest r){AdPackage p=packageById(r.packageId());if(!p.getActive())throw bad("Gói quảng cáo không hoạt động");if(!r.endsAt().isAfter(r.startsAt()))throw bad("Thời gian campaign không hợp lệ");AdCampaign c=new AdCampaign();c.setOrganizerId(organizer);c.setAdPackage(p);c.setName(r.name());c.setPricingMode(r.pricingMode());c.setStartsAt(r.startsAt());c.setEndsAt(r.endsAt());c.setEscrowAmount(r.pricingMode()==PricingMode.POSTPAID_ESCROW?Optional.ofNullable(r.escrowAmount()).orElse(p.getPrice()):BigDecimal.ZERO);c.setFeeAmount(r.pricingMode()==PricingMode.PREPAID?p.getPrice():BigDecimal.ZERO);return camp(campaigns.save(c));} public List<Responses.CampaignResponse> organizerCampaigns(UUID id){return campaigns.findByOrganizerId(id).stream().map(this::camp).toList();} @Transactional @CacheEvict(value="public-banners",allEntries=true) public Responses.CampaignResponse approve(UUID id){AdCampaign c=campaign(id);c.setStatus(CampaignStatus.APPROVED);c.setRejectionReason(null);return camp(campaigns.save(c));} @Transactional public Responses.CampaignResponse reject(UUID id,String reason){AdCampaign c=campaign(id);c.setStatus(CampaignStatus.REJECTED);c.setRejectionReason(reason);return camp(campaigns.save(c));} public BigDecimal postpaidFee(UUID id){AdCampaign c=campaign(id);if(c.getPricingMode()!=PricingMode.POSTPAID_ESCROW)throw bad("Campaign không phải POSTPAID_ESCROW");return c.getAdPackage().getPrice();} @Transactional public void publishSettlement(UUID id){AdCampaign c=campaign(id);if(c.getPricingMode()!=PricingMode.POSTPAID_ESCROW)throw bad("Campaign không phải POSTPAID_ESCROW");c.setFeeAmount(postpaidFee(id));c.setSettlementPublished(true);campaigns.save(c);}
 @Transactional @CacheEvict(value="public-banners",allEntries=true) public Responses.BannerResponse banner(Requests.BannerRequest r){Banner b=new Banner();fill(b,r);return ban(banners.save(b));} @Transactional @CacheEvict(value="public-banners",allEntries=true) public Responses.BannerResponse bannerUpdate(UUID id,Requests.BannerRequest r){Banner b=banner(id);fill(b,r);return ban(banners.save(b));} @Transactional @CacheEvict(value="public-banners",allEntries=true) public Responses.BannerResponse requestImageChange(UUID id,String url){Banner b=banner(id);b.setPendingImageUrl(url);return ban(banners.save(b));} @Transactional @CacheEvict(value="public-banners",allEntries=true) public Responses.BannerResponse approveImage(UUID id){Banner b=banner(id);if(b.getPendingImageUrl()==null)throw bad("Không có ảnh chờ duyệt");b.setImageUrl(b.getPendingImageUrl());b.setPendingImageUrl(null);return ban(banners.save(b));} @Cacheable("public-banners") public List<Responses.BannerResponse> publicBanners(){return banners.findPublic(LocalDateTime.now()).stream().map(this::ban).toList();} public void deleteBanner(UUID id){banners.delete(banner(id));}
 private void fill(Banner b,Requests.BannerRequest r){if(!r.endsAt().isAfter(r.startsAt()))throw bad("Thời gian banner không hợp lệ");b.setCampaign(campaign(r.campaignId()));if(r.imageUrl()!=null)b.setImageUrl(r.imageUrl());if(b.getImageUrl()==null)throw bad("Thiếu ảnh banner");b.setPosition(r.position());b.setPriority(Optional.ofNullable(r.priority()).orElse(0));b.setStartsAt(r.startsAt());b.setEndsAt(r.endsAt());b.setActive(r.active()==null||r.active());} private AdPackage packageById(UUID id){return packages.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy gói"));} private AdCampaign campaign(UUID id){return campaigns.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy campaign"));} private Banner banner(UUID id){return banners.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy banner"));} private AppException bad(String m){return new AppException(ErrorCode.BAD_REQUEST,m);} private Responses.PackageResponse pkg(AdPackage p){return new Responses.PackageResponse(p.getId(),p.getName(),p.getDescription(),p.getPrice(),p.getDurationDays(),p.getActive());} private Responses.CampaignResponse camp(AdCampaign c){return new Responses.CampaignResponse(c.getId(),c.getOrganizerId(),c.getAdPackage().getId(),c.getName(),c.getPricingMode(),c.getStatus(),c.getFeeAmount(),c.getEscrowAmount(),c.getSettlementPublished(),c.getRejectionReason());} private Responses.BannerResponse ban(Banner b){return new Responses.BannerResponse(b.getId(),b.getCampaign().getId(),b.getImageUrl(),b.getPendingImageUrl(),b.getPosition(),b.getPriority(),b.getStartsAt(),b.getEndsAt());}}
